    List<PermOptionDto> self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    for (final item in self) {
      sse_encode_perm_option_dto(item, serializer);
    }
  }

  @protected
  void sse_encode_list_prim_u_8_strict(
    Uint8List self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    serializer.buffer.putUint8List(self);
  }

  @protected
  void sse_encode_list_session_meta_dto(
    List<SessionMetaDto> self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    for (final item in self) {
      sse_encode_session_meta_dto(item, serializer);
    }
  }

  @protected
  void sse_encode_opt_String(String? self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_String(self, serializer);
    }
  }

  @protected
  void sse_encode_payload_dto(PayloadDto self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case PayloadDto_AgentMessage(text: final text):
        sse_encode_i_32(0, serializer);
        sse_encode_String(text, serializer);
      case PayloadDto_Thought(text: final text):
        sse_encode_i_32(1, serializer);
        sse_encode_String(text, serializer);
      case PayloadDto_UserMessage(text: final text):
        sse_encode_i_32(2, serializer);
        sse_encode_String(text, serializer);
      case PayloadDto_ToolCall(
        id: final id,
        kind: final kind,
        title: final title,
        command: final command,
        status: final status,
        content: final content,
        locations: final locations,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_String(id, serializer);
        sse_encode_String(kind, serializer);
        sse_encode_String(title, serializer);
        sse_encode_opt_String(command, serializer);
        sse_encode_String(status, serializer);
        sse_encode_list_content_dto(content, serializer);
        sse_encode_list_String(locations, serializer);
      case PayloadDto_ToolCallUpdate(
        id: final id,
        status: final status,
        content: final content,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_String(id, serializer);
        sse_encode_String(status, serializer);
        sse_encode_list_content_dto(content, serializer);
      case PayloadDto_Plan(entries: final entries):
        sse_encode_i_32(5, serializer);
        sse_encode_list_String(entries, serializer);
      case PayloadDto_Usage(input: final input, output: final output):
        sse_encode_i_32(6, serializer);
        sse_encode_u_64(input, serializer);
        sse_encode_u_64(output, serializer);
    }
  }

  @protected
  void sse_encode_perm_option_dto(
    PermOptionDto self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.id, serializer);
    sse_encode_String(self.label, serializer);
  }

  @protected
  void sse_encode_permission_req_dto(
    PermissionReqDto self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.session, serializer);
    sse_encode_String(self.id, serializer);
    sse_encode_String(self.command, serializer);
    sse_encode_list_perm_option_dto(self.options, serializer);
  }

  @protected
  void sse_encode_session_meta_dto(
    SessionMetaDto self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.id, serializer);
    sse_encode_String(self.title, serializer);
    sse_encode_bool(self.running, serializer);
    sse_encode_u_64(self.lastSeq, serializer);
  }

  @protected
  void sse_encode_u_64(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }

  @protected
  void sse_encode_update_dto(UpdateDto self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.session, serializer);
    sse_encode_u_64(self.seq, serializer);
    sse_encode_u_64(self.turn, serializer);
    sse_encode_payload_dto(self.payload, serializer);
  }

  @protected
  void sse_encode_usize(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_i_32(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putInt32(self);
  }
}

@sealed
class RustClientImpl extends RustOpaque implements RustClient {
  // Not to be used by end users
  RustClientImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  RustClientImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_RustClient,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_RustClient,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_RustClientPtr,
  );

  /// Connect to a host and return a session. Call [`RustSession::events`] to
  /// start the inbound stream; send back via the session's other methods.
  Future<RustSession> connect({required String hostNodeIdHex}) =>
      RustLib.instance.api.crateApiClientRustClientConnect(
        that: this,
        hostNodeIdHex: hostNodeIdHex,
      );

  /// The hosts this client has paired with, hex node ids.
  Future<List<String>> hostsHex() =>
      RustLib.instance.api.crateApiClientRustClientHostsHex(that: this);

  /// This device's node id, hex-encoded.
  String nodeIdHex() =>
      RustLib.instance.api.crateApiClientRustClientNodeIdHex(that: this);

  /// Pair with a host addressed by its hex node id, using `code`.
  Future<String> pair({
    required String code,
    required String hostNodeIdHex,
    String? fcm,
  }) => RustLib.instance.api.crateApiClientRustClientPair(
    that: this,
    code: code,
    hostNodeIdHex: hostNodeIdHex,
    fcm: fcm,
  );
}

